command:
$ErrorActionPreference = "Stop"
git fetch origin main work/content-search --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "28b60642923cf3280f04b43c2322f50eea3b07b1") { throw "main moved" }
if ((git rev-parse origin/work/content-search).Trim() -ne "651ee13c8edfbdd91cb28f34234fcfb610b53df2") { throw "candidate moved" }

git checkout work/content-search
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/content-search
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

$delta=@(git diff --name-only be06aa79c2af74797b9df0c6cbbb25aad1cf81a1..HEAD)
if ($delta.Count -ne 1 -or $delta[0] -ne "tests/winui/m19/m19_native_fixture.cpp") {
  $delta | ForEach-Object { Write-Host $_ }
  throw "post-source-pass revision changed more than native fixture"
}
if (-not (Test-Path "logs\remote-evidence\content-search-before.png")) {
  throw "validated baseline screenshot missing"
}
if (-not (Test-Path "logs\capture-content-visual.py")) {
  throw "content visual capture helper missing"
}

Write-Host "M19_NATIVE_RELEASE"
cmd /c tests\winui\m19\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M19 Release build failed" }
cmd /c "set FLY_M19_CONFIG=Release&& python -X utf8 tests\winui\m19\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M19 native fixture failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "OWNED_M19_GUI"
$env:FLY_MIGRATION_CONFIGURATION="Release"
$env:FLY_M19_OWNED_FEATURES="YES"
python -X utf8 tests\winui\test_shell_gui.py
if ($LASTEXITCODE -ne 0) { throw "owned content-search GUI failed" }

python -X utf8 "logs\capture-content-visual.py" "logs\remote-evidence\content-search-after.png" content
if ($LASTEXITCODE -ne 0) { throw "candidate visual capture failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

@"
feature=bounded-content-search
main=28b60642923cf3280f04b43c2322f50eea3b07b1
candidate=651ee13c8edfbdd91cb28f34234fcfb610b53df2
source_contract_run=37172317827
"@ | Set-Content -Encoding UTF8 "logs\remote-evidence\manifest.txt"
Write-Host "CONTENT_SEARCH_PREMAIN_PASS"
